    private static partial Regex ConMonedaDespues();

    [GeneratedRegex(@"(?<![\d.,])(?<n>\d{1,3}(?:[.,]\d{3})+)(?!\d)")]
    private static partial Regex ConSeparadorDeMiles();

    [GeneratedRegex(@"\d[\d.,]*\d|\d")]
    private static partial Regex Numero();
}

